module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);

wire and_ab, and_cd;

// First layer: two AND gates using gate primitives
and (and_ab, a, b);
and (and_cd, c, d);

// Second layer: OR gate combining the two AND outputs
or  (out, and_ab, and_cd);

// Inverted output generated by continuous assignment for efficiency
assign out_n = ~out;

endmodule